head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setDisabled(!gridView1.getDisabled());
};
scwin.trigger2_onclick = function(e) {
    gridView1.setCellDisabled(0, "col1", !gridView1.getCellDisabled(0, "col1"));
};
scwin.aa = function(row, col) {
    window.log = "clickeD=" + row + "," + col;
    console.log("clickeD=" + row + "," + col);
}
scwin.bb = function(headerId) {
    window.log1 = "headerclicked=" + headerId;
    console.log("headerclicked=" + headerId);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 키보드의 F12를 클릭한다.
    //1. After running the sample file, click F12 on the keyboard.
    //Verify step 1. The console window is displayed.
    //Test step 2. 체크박스가 아닌 바로옆의 빈영역을 클릭한다.
    //2. Click in the blank area next to the check box.
    //Verify step 2. There is no change in the console (previously numbered by the number of clicks)
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log1 == ''", "true");
    WebSquare.wUnit.addCommand("assert", "window.log == ''", "true");
    //Test step 3. name2항목의 header를 여러번 클릭한다.
    //3. Click many times the header of the name2 entry.
    //Verify step 3. The number of clicks is displayed in the console window.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log1 == 'headerclicked=column3'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log1 == 'headerclicked=column3'", "true");
    //Test step 4. name3항목의 필드를 여러번 클릭한다.
    //4. Click many times the field in the name3 field.
    //Verify step 4. The number of clicks is displayed in the console window.
    WebSquare.wUnit.addCommand("set", "window.log = ''");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log == 'clickeD=0,2'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "window.log == 'clickeD=0,2'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData(["1", 1, 2, "0", 3, 4, "1", 5, 6, "0", 7, 8, "1", 1, 2, "0", 3, 4, "1", 5, 6, "0", 7, 8, "1", 1, 2, "0", 3, 4, "1", 5, 6, "0", 7, 8]);
    window.log = "";
    window.log1 = "";
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
